// Get article data - may come from direct path or image generation path
let article = $input.first().json;

// If coming from image generation path, input won't have article content
// Try multiple upstream nodes to find the full article data
if (!article['Content EN'] || (article['Content EN'] || '').trim().length < 100) {
  const nodesToTry = ['Has Image URL?', 'Prepare Article (Manual)', 'Should Publish Today?'];
  let found = false;

  for (const nodeName of nodesToTry) {
    try {
      const items = $(nodeName).all();
      for (const item of items) {
        if (item.json['Content EN'] && item.json['Content EN'].trim().length > 100) {
          article = {...item.json};
          // Update Image URL since it was just generated
          if (!article['Image URL'] || article.needsImageGeneration) {
            article['Image URL'] = `https://raw.githubusercontent.com/MyDigipal/mydigipal-website/main/public/images/Blog%20Thumbnails/${article.Slug}.png`;
          }
          found = true;
          break;
        }
      }
      if (found) break;
    } catch (e) {
      continue;
    }
  }

  if (!found) {
    // Last resort fallback
    article = $input.first().json;
  }
}

let contentEN = article['Content EN'] || '';
// Escape bare {Word} patterns that MDX would interpret as JSX expressions
contentEN = contentEN.replace(/(?<!\\)\{([A-Za-z_][A-Za-z0-9_]*)\}/g, '\\{$1\\}');

// SAFETY NET: Si le contenu est vide/trop court, BLOQUER la publication
const MIN_CHARS = 6000;
const MIN_WORDS = 1000;
const wordCount = contentEN.trim().split(/\s+/).filter(w => w.length > 0).length;
if (!contentEN || contentEN.trim().length < MIN_CHARS || wordCount < MIN_WORDS) {
  throw new Error(`BLOQUE: Le contenu EN de l'article "${article['Title EN']}" est insuffisant (${contentEN.trim().length} chars, ${wordCount} mots). Minimum: ${MIN_CHARS} chars / ${MIN_WORDS} mots.`);
}

// ============ META DESCRIPTION VALIDATION & FIX ============
let description = (article['Description EN'] || '').trim();
const originalLength = description.length;

if (description.length > 160) {
  console.warn(`[WARNING] Description EN too long: ${description.length} chars - truncating`);
  const truncated = description.substring(0, 160);
  const lastPeriod = truncated.lastIndexOf('.');
  if (lastPeriod > 100) {
    description = truncated.substring(0, lastPeriod + 1);
  } else {
    const lastSpace = truncated.lastIndexOf(' ');
    description = truncated.substring(0, lastSpace) + '...';
  }
}

if (description.length > 0 && !description.endsWith('.') && !description.endsWith('...')) {
  description = description + '.';
}

console.log(`Description EN: ${originalLength} -> ${description.length} chars`);
// ===========================================================

const VALID_CATEGORIES = ['abm', 'ai', 'paid-ads', 'seo', 'marketing-ops', 'strategy', 'company-news'];
const CATEGORY_MAP = {
  'digital marketing': 'strategy',
  'automotive': 'strategy',
  'b2b-marketing': 'strategy',
  'b2b marketing': 'strategy',
  'content': 'strategy',
  'social media': 'strategy',
  'email': 'marketing-ops',
  'email marketing': 'marketing-ops',
  'tracking': 'marketing-ops',
  'analytics': 'marketing-ops',
  'google ads': 'paid-ads',
  'linkedin ads': 'paid-ads',
  'meta ads': 'paid-ads',
  'facebook ads': 'paid-ads',
  'artificial intelligence': 'ai',
  'machine learning': 'ai',
  'account-based marketing': 'abm',
  'search engine optimization': 'seo'
};

let category = (article.Category || 'strategy').toLowerCase().trim();
if (!VALID_CATEGORIES.includes(category)) {
  category = CATEGORY_MAP[category] || 'strategy';
}

let industry = (article.Industry || 'general').toLowerCase().trim();
const VALID_INDUSTRIES = ['automotive', 'b2b-tech', 'general'];
if (!VALID_INDUSTRIES.includes(industry)) { industry = 'general'; }

if (!contentEN.startsWith('---')) {
  const today = new Date().toISOString().split('T')[0];
  const frontmatter = `---\ntitle: "${(article['Title EN'] || 'Untitled').replace(/"/g, '\\"')}"\ndescription: "${description.replace(/"/g, '\\"')}"\ndate: ${today}\ncategory: "${category}"\nindustry: "${industry}"\nimage: "${article['Image URL'] || '/images/Blog Thumbnails/default-blog.png'}"\nauthor: "MyDigipal Team"\ntags: ${JSON.stringify(article.Tags ? article.Tags.split(',').map(t => t.trim()) : [])}\nfeatured: ${article.Featured === 'true' || article.Featured === true}\ndraft: false\n---\n\n`;
  contentEN = frontmatter + contentEN;
}

return [{
  json: {
    path: `src/content/blog/en/${article.Slug}.mdx`,
    content: contentEN,
    slug: article.Slug,
    title: article['Title EN'],
    row_number: article.row_number
  }
}];

